'use strict';
const R=DayProtocol,KEY='day-protocol-v1',$=s=>document.querySelector(s),names=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'],periods={morning:'Morning',day:'Afternoon',evening:'Evening'};
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateText=d=>R.parse(d).toLocaleDateString('en-GB',{day:'numeric',month:'long'});
let state={version:2,habits:[],logs:{}},selected=R.today(),view='today',month=selected.slice(0,7),editing=null,archiveView=false,filter='all',statsHabit='',timer,undoAction,blocked=false,importData=null,editSnapshot='',lastDay=R.today();
const templates=[{name:'Read a book',icon:'📖',type:'count',target:20,unit:'pages',step:5,period:'evening'},{name:'Drink water',icon:'💧',type:'count',target:8,unit:'cups',step:1,period:'day'},{name:'Morning exercise',icon:'☀',type:'minutes',target:10,unit:'min',step:5,period:'morning'},{name:'Learn English',icon:'✦',type:'minutes',target:15,unit:'min',step:5,period:'day'}];
function notify(message,undo){clearTimeout(timer);undoAction=undo;$('#toast').innerHTML=`<span>${esc(message)}</span>${undo?'<button id="undo">Undo</button>':''}`;$('#toast').classList.add('visible');timer=setTimeout(()=>{$('#toast').classList.remove('visible');undoAction=null},undo?9000:5000)}
function load(){try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);state=R.migrate(parsed);if(!parsed.version&&!localStorage.getItem('day-protocol-before-v2'))localStorage.setItem('day-protocol-before-v2',raw)}}catch{blocked=true}}
async function transact(action){
  if(window.DayProtocolWriting){notify('Please wait for the previous action to finish saving.');return false}
  if(blocked){notify(DayProtocolCloud.launched?'First load your progress from Telegram.':'First restore your data from a backup.');return false}
  window.DayProtocolWriting=true;
  try{const raw=DayProtocolCloud.launched?null:localStorage.getItem(KEY),next=raw?R.migrate(JSON.parse(raw)):structuredClone(state);action(next);if(!R.validate(next))throw Error('Invalid data');
    if(DayProtocolCloud.launched)state=await DayProtocolCloud.save(next);else{localStorage.setItem(KEY,JSON.stringify(next));state=next}render();return true;
  }catch(e){notify(DayProtocolCloud.launched?e.message:e.message.startsWith('Habit')?e.message:'Could not save. Check browser storage and export a backup.');const draftButton=$('#cloud-draft');if(draftButton)draftButton.hidden=!DayProtocolCloud.draft;return false}
  finally{window.DayProtocolWriting=false}
}
async function progress(id,amount,date=selected){if(!Number.isInteger(amount)||amount<0||amount>100000||date>R.today())return false;let previous=0;const ok=await transact(s=>{const h=s.habits.find(h=>h.id===id);if(!h||!R.scheduled(s,h,date))throw Error('Habit is not available on this day.');previous=R.value(s,h,date);s.logs[date]??={};s.logs[date][id]=amount});if(ok)notify(amount?'Progress saved':'Check-in removed',()=>transact(s=>{if(s.logs[date]?.[id]!==amount)throw Error('Habit has already changed in another tab.');s.logs[date][id]=previous}));return ok}
function row(h,management=false){const c=R.configAt(h,selected),v=R.value(state,h,selected),done=R.done(state,h,selected),w=R.weekly(state,h,selected),s=R.streak(state,h);const schedule=h.schedule==='weekly'?`${h.frequency} times a week`:h.days.length===7?'Every day':h.days.map(d=>names[d]).join(', '),upcoming=h.revisions.find(r=>r.from>R.today());return `<article class="habit ${done?'done':''}" data-habit="${h.id}"><div class="habit-icon">${esc(h.icon)}</div><div class="habit-info"><strong>${esc(h.name)}</strong><small>${management?esc(schedule):c.type==='check'?(done?'Done':'One step towards your goal'):`${v} of ${c.target} ${esc(c.unit)}`}${!management&&c.schedule==='weekly'?` · ${w.complete}/${w.target} this week`:''}${s.current?` <span class="streak">${s.current} ${s.unit} in a row</span>`:''}</small>${upcoming?`<small class="upcoming">New goal starts ${dateText(upcoming.from)}</small>`:''}${!management&&c.type!=='check'?`<div class="track"><span style="width:${Math.min(v/c.target*100,100)}%"></span></div>`:''}</div><div class="habit-actions">${management?`<button class="text-button" data-archive="${h.id}">${h.archivedAt?'Restore':'Archive'}</button>`:c.type!=='check'?`<div class="quantity"><button data-minus="${h.id}" aria-label="Decrease: ${esc(h.name)}" ${v===0?'disabled':''}>−</button><button class="value-button" data-value="${h.id}" aria-label="Enter progress: ${esc(h.name)}">${v}</button><button data-plus="${h.id}" aria-label="Add: ${esc(h.name)}">+</button></div>`:''}${management?'':`<button class="complete" data-check="${h.id}" aria-pressed="${done}" aria-label="${done?'Undo':'Complete'}: ${esc(h.name)}">✓</button>`}<button class="edit" data-edit="${h.id}" aria-label="Edit: ${esc(h.name)}">⋯</button></div></article>`}
function weekStrip(){const start=R.monday(selected);return `<div class="week-toolbar"><button class="icon-button" data-week="-7" aria-label="Previous week">‹</button><span>${dateText(start)} — ${dateText(R.shift(start,6))}</span><button class="text-button" data-today ${selected===R.today()?'disabled':''}>Today</button><button class="icon-button" data-week="7" aria-label="Next week" ${R.shift(start,7)>R.today()?'disabled':''}>›</button></div><div class="week">${Array.from({length:7},(_,i)=>{const d=R.shift(start,i),t=R.dayStats(state,d);return `<button class="day ${d===selected?'selected':''} ${d===R.today()?'is-today':''}" data-date="${d}" aria-label="${dateText(d)}: ${t.complete} of ${t.total}" aria-pressed="${d===selected}" ${d>R.today()?'disabled':''}><span>${names[i]}</span><b>${R.parse(d).getDate()}</b><i class="${t.complete?'marked':''}"></i></button>`}).join('')}</div>`}
function sidebar(){const w=R.weekStats(state,selected),start=R.monday(selected),victories=Object.entries(state.logs).reduce((n,[d,logs])=>n+state.habits.filter(h=>(logs[h.id]||0)>=R.configAt(h,d).target).length,0);return `<div class="right-column"><section class="card week-card"><div class="card-label">WEEKLY OVERVIEW</div><div class="big-number">${w.percent}<span>%</span></div><p class="muted">${w.complete} of ${w.target} goals completed</p><div class="bars" aria-label="Daily habit completion by day">${Array.from({length:7},(_,i)=>{const d=R.shift(start,i),t=R.dayStats(state,d),p=t.total?t.complete/t.total*100:0;return `<div class="bar-column"><div class="bar-space"><div class="bar ${d===selected?'today':''}" style="height:${Math.max(p,4)}%" title="${dateText(d)}: ${t.complete} of ${t.total}"></div></div><span>${names[i]}</span></div>`}).join('')}</div><p class="muted footnote">Daily goals count through today.<br>Weekly goals cover the whole week.</p></section><section class="card"><h2>Your small wins</h2><div class="stat-line"><span>Total completions</span><b>${victories}</b></div><div class="stat-line"><span>Active habits</span><b>${state.habits.filter(h=>!h.archivedAt).length}</b></div></section><section class="card tip"><div class="tip-icon">✧</div><strong>Coming back is a habit, too</strong><p>Missing a day doesn’t erase your progress. Pick up where you are.</p></section></div>`}
function starter(){return `<section class="starter"><div class="starter-top"><span class="starter-symbol">✦</span><h2>One habit is a great start</h2><p>Choose an example and make it yours.</p></div><div class="template-grid">${templates.map((t,i)=>`<button class="template" data-template="${i}"><span>${t.icon}</span><strong>${t.name}</strong><small>${t.target} ${t.unit} per day</small><b>+</b></button>`).join('')}</div><button class="text-button" data-create>Create your own habit</button></section>`}
function todayPage(){const t=R.dayStats(state,selected),daily=R.daily(state,selected),weekly=state.habits.filter(h=>R.scheduled(state,h,selected)&&R.configAt(h,selected).schedule==='weekly'),show=h=>filter==='all'||(filter==='todo'?!R.done(state,h,selected):R.done(state,h,selected));return `<div class="dashboard"><div class="main-column"><section class="summary ${t.total&&t.complete===t.total?'is-complete':''}"><div><div class="eyebrow">${selected===R.today()?'TODAY’S PROTOCOL':dateText(selected).toUpperCase()}</div><h2>${t.total?`${t.complete} of ${t.total} completed`:weekly.length?'This week':state.habits.length?'A day to recharge':'Start with one small step'}</h2><p>${t.total?(t.complete===t.total?'Daily plan complete. Well done.':`Remaining ${t.total-t.complete}. Keep going at your own pace.`):(weekly.length?'Choose a day that works for your weekly goal.':state.habits.length?'Take a break today or work on your weekly goals.':'Choose an example below or create your own habit.')}</p></div><div class="ring" style="--progress:${t.total?t.complete/t.total*100:0}%" aria-label="${t.complete} of ${t.total} daily habits"><div><b>${t.total?Math.round(t.complete/t.total*100):0}%</b><small>today</small></div></div></section>${weekStrip()}${!state.habits.length?starter():`<div class="section-title"><h2>Daily plan</h2><div class="segmented" aria-label="Filter habits">${[['all','All'],['todo','Remaining'],['done','Done']].map(([id,label])=>`<button data-filter="${id}" class="${filter===id?'active':''}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div></div>${Object.entries(periods).map(([p,label])=>{const list=daily.filter(h=>h.period===p&&show(h));return list.length?`<div class="period-title"><span>${label}</span><span>${list.length}</span></div>${list.map(h=>row(h)).join('')}`:''}).join('')}${!daily.filter(show).length?`<div class="empty compact ${filter==='todo'&&daily.length?'empty-success':''}">${filter==='done'?'No completed habits yet.':filter==='todo'&&daily.length?'All done for today. Take a breath.':'No daily habits scheduled for this day.'}</div>`:''}${weekly.length?`<div class="section-title weekly-heading"><h2>This week</h2><small>You choose the day</small></div><p class="section-note">These goals do not affect your daily completion percentage.</p>${weekly.filter(show).map(h=>row(h)).join('') || '<div class="empty compact">No habits with this status.</div>'}`:''}`}</div>${sidebar()}</div>`}
function statsPage(){const first=month+'-01',count=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate(),habits=statsHabit?state.habits.filter(h=>h.id===statsHabit):state.habits;let completions=0,activeDays=0;const cells=Array.from({length:count},(_,i)=>{const d=R.shift(first,i),eligible=habits.filter(h=>R.scheduled(state,h,d)),finished=eligible.filter(h=>R.done(state,h,d)).length;completions+=finished;if(finished)activeDays++;return `<button data-date="${d}" class="${finished?(finished===eligible.length?'full':'has'):''} ${d===R.today()?'calendar-today':''}" ${d>R.today()?'disabled':''} aria-label="${dateText(d)}: ${finished} completed"><b>${i+1}</b><small>${finished||'·'}</small></button>`}).join('');return `<div class="stats-toolbar"><label>Habit<select id="stats-habit"><option value="">All habits</option>${state.habits.map(h=>`<option value="${h.id}" ${statsHabit===h.id?'selected':''}>${esc(h.name)}${h.archivedAt?' · archived':''}</option>`).join('')}</select></label><div class="mini-stat"><strong>${completions}</strong><span>completions this month</span></div><div class="mini-stat"><strong>${activeDays}</strong><span>days with progress</span></div></div>${analyticsPanel()}<div class="stats-grid"><section class="card calendar-card"><div class="month-nav"><button class="icon-button" data-month="-1" aria-label="Previous month">‹</button><h2>${R.parse(first).toLocaleDateString('en-GB',{month:'long',year:'numeric'})}</h2><button class="icon-button" data-month="1" aria-label="Next month" ${month>=R.today().slice(0,7)?'disabled':''}>›</button></div><div class="calendar">${names.map(n=>`<span>${n}</span>`).join('')}${'<span></span>'.repeat(R.weekday(first))}${cells}</div><div class="legend"><span><i></i> No check-ins</span><span><i class="some"></i> Some progress</span><span><i class="all"></i> All done</span></div><p class="muted">Select a day to view its habits and adjust your progress.</p></section><section class="card"><h2>Consistency</h2><p class="muted">Streaks follow your schedule. Rest days and archived periods do not break a streak.</p>${habits.map(h=>{const s=R.streak(state,h);return `<div class="streak-row"><div class="habit-icon">${esc(h.icon)}</div><div><strong>${esc(h.name)}</strong><small>Best streak: ${s.best} ${s.unit}</small></div><b>${s.current}<small>${s.unit}</small></b></div>`}).join('')||'<div class="empty compact">Your first check-in starts your story.</div>'}</section></div>`}
function habitsPage(){const list=state.habits.filter(h=>!!h.archivedAt===archiveView);return `<div class="section-title"><div class="segmented"><button data-archive-view="false" class="${!archiveView?'active':''}">Active (${state.habits.filter(h=>!h.archivedAt).length})</button><button data-archive-view="true" class="${archiveView?'active':''}">Archived (${state.habits.filter(h=>h.archivedAt).length})</button></div><small>${list.length} habits</small></div>${list.length?list.map(h=>row(h,true)).join(''):archiveView?'<div class="empty">Your archive is empty. Habits you set aside will appear here.</div>':starter()}`}
function render(){const focusData=document.activeElement?.dataset;document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false')});$('#page-label').textContent={today:'Today',stats:'Statistics',habits:'My habits'}[view];$('#date-label').textContent=R.parse(selected).toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'}).toUpperCase();$('#title').innerHTML={today:'Your day<span>.</span>',stats:'Your progress in detail<span>.</span>',habits:'Your habits<span>.</span>'}[view];$('#subtitle').textContent={today:'Focus on what matters today.',stats:'Notice your consistency, not just your perfect days.',habits:'Set goals that work for you.'}[view];$('#storage-warning').hidden=!blocked;$('#content').innerHTML=view==='today'?todayPage():view==='stats'?statsPage():habitsPage();if(focusData)for(const attr of ['plus','minus','check','filter','week'])if(focusData[attr]!==undefined){document.querySelector(`[data-${attr}="${CSS.escape(focusData[attr])}"]`)?.focus({preventScroll:true});break}}
function openEditor(id,templateIndex){const h=state.habits.find(h=>h.id===id),preset=templates[templateIndex];editing=h?.id||null;editSnapshot=h?JSON.stringify(h):'';const defaults={name:'',type:'check',target:1,unit:'times',step:1,period:'morning',icon:'☀',schedule:'days',frequency:3,days:[0,1,2,3,4,5,6]},data={...defaults,...(h||preset||{})},f=$('#habit-form');f.reset();$('#dialog-title').textContent=h?'Edit habit':'New habit';for(const field of ['name','type','target','unit','step','period','icon','schedule','frequency'])f.elements[field].value=data[field];$('#days').innerHTML='<legend>Days of the week</legend>'+names.map((n,i)=>`<label><input type="checkbox" value="${i}" ${data.days.includes(i)?'checked':''}><span>${n}</span></label>`).join('');$('#edit-history-note').hidden=!h;$('#form-error').textContent='';scheduleFields();$('#editor').showModal();f.elements.name.focus()}
function scheduleFields(){const f=$('#habit-form'),weekly=f.elements.schedule.value==='weekly',check=f.elements.type.value==='check';$('#days').hidden=weekly;$('#weekly-label').hidden=!weekly;f.elements.frequency.disabled=!weekly;$('#goal-details').hidden=check;for(const k of ['target','unit','step'])f.elements[k].disabled=check;if(f.elements.type.value==='minutes'){f.elements.unit.value='min';f.elements.unit.readOnly=true}else f.elements.unit.readOnly=false}
$('#habit-form').addEventListener('change',scheduleFields);
$('#habit-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.target,days=[...$('#days').querySelectorAll('input:checked')].map(i=>Number(i.value)),name=f.elements.name.value.trim();if(!name||(!days.length&&f.elements.schedule.value==='days')){$('#form-error').textContent=!name?'Enter a habit name.':'Choose at least one day of the week.';return}const changes={name,type:f.elements.type.value,target:f.elements.type.value==='check'?1:Number(f.elements.target.value),unit:f.elements.unit.value.trim()||'times',step:Number(f.elements.step.value)||1,period:f.elements.period.value,icon:f.elements.icon.value,schedule:f.elements.schedule.value,frequency:Number(f.elements.frequency.value)||3,days:days.length?days:[0,1,2,3,4,5,6]};let effective=null;const ok=await transact(s=>{if(editing){const h=s.habits.find(h=>h.id===editing);if(!h||JSON.stringify(h)!==editSnapshot)throw Error('Habit changed in another tab. Please reopen the editor.');effective=R.revise(h,changes)}else{const h={...changes,id:crypto.randomUUID(),created:R.today(),archivedAt:null,pauses:[]};h.revisions=[{from:h.created,...R.config(h)}];s.habits.push(h)}});if(ok){$('#editor').close();notify(effective?`Your new goal starts on ${dateText(effective)}. Your history is preserved.`:'Habit saved')}});
function openValue(id){const h=state.habits.find(h=>h.id===id),c=R.configAt(h,selected);$('#progress-form').dataset.id=id;$('#progress-form').dataset.date=selected;$('#progress-title').textContent=h.name;$('#progress-description').textContent=`${dateText(selected)} · goal ${c.target} ${c.unit}`;$('#amount').value=R.value(state,h,selected);$('#progress-dialog').showModal();$('#amount').select()}
$('#progress-form').onsubmit=async e=>{e.preventDefault();if(await progress(e.target.dataset.id,Number($('#amount').value),e.target.dataset.date))$('#progress-dialog').close()};
function download(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportData(){if(blocked){notify('Current data could not be read. Restore a valid backup.');return}download(state,`day-protocol-${R.today()}.json`);notify('Backup downloaded')}
$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw Error();importData=R.migrate(JSON.parse(await file.text()));$('#import-summary').textContent=`This backup contains: ${importData.habits.length} habits and ${Object.keys(importData.logs).length} days with check-ins. Your current data will be replaced. A local copy will be saved first.`;$('#import-dialog').showModal()}catch{notify('The backup is damaged or uses an unsupported format. Your current data is unchanged.')}finally{e.target.value=''}};
$('#confirm-import').onclick=async()=>{if(!importData)return;if(DayProtocolCloud.launched){const imported=importData;if(await transact(s=>{s.version=imported.version;s.habits=imported.habits;s.logs=imported.logs})){importData=null;$('#import-dialog').close();notify('Backup saved in Telegram')}return;}try{const current=localStorage.getItem(KEY);if(current)localStorage.setItem('day-protocol-before-import',current);localStorage.setItem(KEY,JSON.stringify(importData));state=importData;blocked=false;importData=null;$('#import-dialog').close();render();notify('Data restored')}catch{notify('Could not restore the backup. Your current data is preserved.')}};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(d.view){view=d.view;if(view==='today')selected=R.today();render()}if(d.create!==undefined||b.id==='add')openEditor();if(d.template!==undefined)openEditor(null,Number(d.template));if(d.close)$('#'+d.close).close();if(d.edit)openEditor(d.edit);if(d.value)openValue(d.value);if(d.date){selected=d.date;view='today';filter='all';render()}if(d.today!==undefined){selected=R.today();filter='all';render()}if(d.week){selected=R.shift(selected,Number(d.week));if(selected>R.today())selected=R.today();filter='all';render()}if(d.filter){filter=d.filter;render()}if(d.archiveView){archiveView=d.archiveView==='true';render()}if(d.month){const date=R.parse(month+'-01');date.setMonth(date.getMonth()+Number(d.month));month=R.key(date).slice(0,7);render()}for(const action of ['plus','minus','check'])if(d[action]){const h=state.habits.find(h=>h.id===d[action]),c=R.configAt(h,selected),v=R.value(state,h,selected);progress(h.id,action==='check'?(R.done(state,h,selected)?0:c.target):Math.max(0,Math.min(100000,v+(action==='plus'?c.step:-c.step))))}if(d.archive){let before,after;const ok=await transact(s=>{const h=s.habits.find(h=>h.id===d.archive);if(!h)throw Error('Habit no longer exists.');before=structuredClone(h);h.archivedAt?R.restore(h):R.archive(h);after=JSON.stringify(h)});if(ok)notify(before.archivedAt?'Habit restored':'Habit archived. Your history is preserved.',()=>transact(s=>{const index=s.habits.findIndex(h=>h.id===d.archive);if(index<0||JSON.stringify(s.habits[index])!==after)throw Error('Habit has already changed.');s.habits[index]=before}))}if(d.export!==undefined||b.id==='export')exportData();if(d.import!==undefined||b.id==='import')$('#import-file').click();if(b.id==='undo'&&undoAction){const action=undoAction;undoAction=null;if(await action())notify('Action undone')}if(d.recover!==undefined){try{const raw=localStorage.getItem('day-protocol-before-import')||localStorage.getItem('day-protocol-before-v2');if(!raw)return notify('No previous local backup is available yet.');download(JSON.parse(raw),`day-protocol-recovery-${R.today()}.json`)}catch{notify('Could not read the local backup.')}}});
document.addEventListener('change',e=>{if(e.target.id==='stats-habit'){statsHabit=e.target.value;render()}});$('.brand').onclick=e=>{e.preventDefault();view='today';selected=R.today();render()};
window.addEventListener('storage',e=>{if(DayProtocolCloud.launched||e.key!==KEY)return;try{state=e.newValue?R.migrate(JSON.parse(e.newValue)):{version:2,habits:[],logs:{}};blocked=false;render()}catch{blocked=true;render()}});
function rollover(){const now=R.today();if(now!==lastDay){if(selected===lastDay)selected=now;month=now.slice(0,7);lastDay=now;render()}}document.addEventListener('visibilitychange',()=>{if(!document.hidden)rollover()});setInterval(rollover,30000);
async function startCloud(){blocked=true;document.documentElement.classList.add('cloud-loading');try{state=R.migrate(await DayProtocolCloud.load());blocked=false;if(state.language&&state.language!==DayLanguage.current){DayLanguage.navigate(state.language);return}render()}catch(e){DayProtocolCloud.status(e.message);notify(e.message)}finally{document.documentElement.classList.remove('cloud-loading')}}
window.addEventListener('day-protocol:cloud-update',e=>{state=R.migrate(e.detail);render()});
window.addEventListener('day-protocol:cloud-conflict',e=>{state=R.migrate(e.detail);render()});
window.addEventListener('day-protocol:cloud-retry',()=>{if(!window.DayProtocolWriting)startCloud()});
DayProtocolCloud.boot();if(DayProtocolCloud.launched){render();startCloud()}else{load();render();}
if(document.modelContext?.registerTool)try{Promise.resolve(document.modelContext.registerTool({name:'read_habits',description:'Read scheduled habits and their progress for the selected date.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({date:selected,habits:state.habits.filter(h=>R.scheduled(state,h,selected)).map(h=>({id:h.id,name:h.name,target:R.configAt(h,selected).target,value:R.value(state,h,selected)}))})})).catch(()=>{})}catch{}
